      "fo_backbones": "Real-world: internet backbones",
      "fo_backbones_detail": "99% of intercontinental data traffic goes over fiber-optic submarine cables.",
      "fo_bdp": "Bandwidth-distance product",
      "fo_bdp_detail": "Single-mode fiber: petabit-per-second times km. Vastly more than copper.",
      "fo_dispersion": "Dispersion",
      "fo_dispersion_detail": "Different wavelengths or modes travel at slightly different speeds → pulse spreading. Limits data rate.",
      "fo_edfa": "EDFA (erbium-doped fiber amp)",
      "fo_edfa_detail": "Amplifies optical signal directly without electrical conversion. Revolutionized long-haul fiber.",
      "fo_endoscopes": "Real-world: medical endoscopes",
      "fo_endoscopes_detail": "Coherent fiber bundles transmit images. Used to inspect inside body.",
      "fo_howwork": "How they work",
      "fo_howwork_detail": "Total internal reflection traps light in core (higher n) surrounded by cladding (lower n). Light bounces along the fiber.",
      "fo_mmf": "Multi-mode fiber (MMF)",
      "fo_mmf_detail": "Core ~50-62.5 μm. Many modes — limits bandwidth-distance product. Short runs (<2 km).",
      "fo_sensors": "Real-world: sensors",
      "fo_sensors_detail": "Fiber Bragg gratings detect strain, temperature. Used in bridges, oil wells, aerospace.",
      "fo_smf": "Single-mode fiber (SMF)",
      "fo_smf_detail": "Core ~9 μm. Only one mode propagates. Long distances (>100 km). Used in telecom backbones.",
      "fo_wdm": "WDM (wavelength division multiplexing)",
      "fo_wdm_detail": "Multiple wavelengths on one fiber. DWDM can fit 100+ channels — Tb/s per fiber.",
      "general_formula": "General Formula",
      "gl_antinode_def": "Point of maximum displacement on a standing wave.",
      "gl_antinode_term": "Antinode",
      "gl_coherence_def": "Constant phase relationship between waves. Required for stable interference patterns. Lasers are highly coherent.",
      "gl_coherence_term": "Coherence",
      "gl_compression_def": "Region of high pressure in a longitudinal wave (sound).",
      "gl_compression_term": "Compression",
      "gl_crest_def": "Highest point of a transverse wave. Maximum positive displacement.",
      "gl_crest_term": "Crest",
      "gl_damping_def": "Loss of amplitude over time due to friction or radiation. Critical damping = fastest decay without overshoot.",
      "gl_damping_term": "Damping",
      "gl_diffraction_def": "Wave bending around obstacles or through apertures. Effect strong when aperture ~ λ.",
      "gl_diffraction_term": "Diffraction",
      "gl_interference_def": "Two waves overlapping. Constructive (in phase) or destructive (out of phase).",
      "gl_interference_term": "Interference",
      "gl_node_def": "Point of zero displacement on a standing wave.",
      "gl_node_term": "Node",
      "gl_photon_def": "Quantum of EM radiation. Energy E = hf. Each photon carries momentum p = h/λ.",
      "gl_photon_term": "Photon",
      "gl_polarization_def": "Direction of oscillation in a transverse wave. Light from sun is unpolarized; passing through a polarizer selects one direction.",
      "gl_polarization_term": "Polarization",
      "gl_rarefaction_def": "Region of low pressure in a longitudinal wave.",
      "gl_rarefaction_term": "Rarefaction",
      "gl_reflection_def": "Wave bouncing off a boundary. Phase flips if going from less to more dense (hard boundary).",
      "gl_reflection_term": "Reflection",
      "gl_refraction_def": "Wave bending as it crosses a boundary where speed changes. Snell's law.",
      "gl_refraction_term": "Refraction",
      "gl_resonance_def": "Large amplitude when driving frequency matches natural frequency. Tacoma Narrows bridge collapse classic example (with caveats).",
      "gl_resonance_term": "Resonance",
      "gl_standingwave_def": "Pattern from two identical waves traveling opposite directions. Nodes + antinodes fixed in space.",
      "gl_standingwave_term": "Standing wave",
      "gl_trough_def": "Lowest point of a transverse wave. Maximum negative displacement.",
      "gl_trough_term": "Trough",
