      "nc_silver": "Silver",
      "nc_silver_notes": "Light gray, often with metallic sheen.",
      "nc_teal": "Teal",
      "nc_teal_notes": "Dark cyan. Named after teal duck's head color.",
      "nc_tomato": "Tomato",
      "nc_tomato_notes": "Bright red-orange.",
      "nc_turquoise": "Turquoise",
      "nc_turquoise_notes": "Greenish blue, named after the gemstone.",
      "nc_violet": "Violet",
      "nc_violet_notes": "Highest energy visible. Beyond is UV.",
      "nc_white": "White",
      "nc_white_notes": "All wavelengths reflected equally.",
      "nc_yellow": "Yellow",
      "nc_yellow_notes": "Brightest perceived color (peak human sensitivity).",
      "nl_concert": "Rock concert / club",
      "nl_concert_notes": "Permanent damage in minutes.",
      "nl_conversation": "Normal conversation",
      "nl_conversation_notes": "At 1 m.",
      "nl_gunshot": "Gunshot",
